import json
from pyproj import Transformer
from shapely.geometry import Polygon, mapping, LineString
s = """-84.54078934866969,39.15311790457358,0 -84.54221282445582,39.15287931626768,0 -84.54324345759572,39.15252838863997,0 -84.54378346713375,39.15219033324864,0 -84.54417545913759,39.15169397441957,0 -84.54607713790759,39.14802430980677,0 -84.54676825859841,39.14755005025448,0 -84.54808701393371,39.14374971031452,0 -84.54819447822167,39.14274937560577,0 -84.54797060979223,39.14158276514305,0 -84.54687634159163,39.13768583223768,0 -84.54594804034519,39.1362399123685,0 -84.54519744896892,39.13508695985118,0 -84.54466594375634,39.13408240178335,0 -84.54346818634343,39.13131302720538,0 -84.54317462818925,39.13024185046189,0 -84.54198933610385,39.12497736895293,0 -84.54476066788588,39.10124869107332,0 -84.54112920885447,39.10100184451483,0 -84.54034889705407,39.10814056207457,0 -84.54098081198828,39.10944501600095,0 -84.54129656711582,39.11183391740869,0 -84.53926353852439,39.12794746712887,0 -84.53915226358816,39.12966482521212,0 -84.53926355511015,39.13094347660309,0 -84.53961594018767,39.132071601574,0 -84.54012267204293,39.13287188137714,0 -84.54394530403755,39.13712043769968,0 -84.54440501275378,39.13784742219215,0 -84.54472394899443,39.1386670766172,0 -84.54489114164724,39.1395051547458,0 -84.54479675676326,39.14059348406449,0 -84.54391239533335,39.14873476219668,0 -84.54356979799837,39.1498902581771,0 -84.54315669622022,39.15074089752746,0 -84.54262583139575,39.15150844313469,0 -84.54206776102903,39.15223298303359,0 -84.54159586401032,39.15263766389116,0 -84.54122291667649,39.1528918006346,0 -84.54078934866969,39.15311790457358,0"""
T = Transformer.from_crs(4326, 26916, always_xy=True)
pts = [T.transform(float(a.split(',')[0]), float(a.split(',')[1])) for a in s.split()]
P = Polygon(pts)
print('valid', P.is_valid, 'area ha %.1f' % (P.area / 1e4), 'bounds', [round(v) for v in P.bounds])
json.dump({'type': 'Feature', 'properties': {'name': 'Ben buildable area 27 Oct'}, 'geometry': mapping(P)}, open('ben_area.json', 'w'))
for n in range(int(P.bounds[1]) // 100 * 100 + 100, int(P.bounds[3]), 200):
    g = LineString([(711000, n), (714000, n)]).intersection(P)
    parts = [(round(q.bounds[0]), round(q.bounds[2])) for q in getattr(g, 'geoms', [g]) if q.length > 1]
    print(n, parts, [b - a for a, b in parts])
